input.command:
cd /home/vercel-sandbox/native; python3 - <<'E'
p='assets/theme-preview.js'
s=open(p).read()
a=s.index("    code.innerHTML = textContent.replace")
b=s.index("    });\n",a)+7
new='''    const frag = document.createDocumentFragment();
    let last = 0;
    for (const match of textContent.matchAll(/oklch\\([^)]+\\)/g)) {
      const m = match[0];
      frag.appendChild(document.createTextNode(textContent.slice(last, match.index)));
      const swatch = document.createElement("span");
      swatch.style.cssText = `background-color:${m};width:.85em;height:.85em;display:inline-block;margin-right:.4em;border-radius:3px;border:1px solid rgba(255,255,255,.15);vertical-align:middle;flex-shrink:0;`;
      frag.appendChild(swatch);
      frag.appendChild(document.createTextNode(m));
      last = match.index + m.length;
    }
    frag.appendChild(document.createTextNode(textContent.slice(last)));
    code.replaceChildren(frag);
'''
s=s[:a]+new+s[b:]
open(p,'w').write(s)
E
sed -n 664,684p assets/theme-preview.js; node --check assets/theme-preview.js && git checkout -q -b fix/theme-preview-xss && git commit -qam "Build theme swatches with DOM nodes instead of innerHTML" && git push -q -u origin HEAD 2>&1|tail -2; git remote -v|head -3

